// beacon-chain/blockchain/process_block.go:549-587
func (s *Service) validateMergeTransitionBlock(ctx context.Context, stateVersion int, stateHeader interfaces.ExecutionData, blk interfaces.ReadOnlySignedBeaconBlock) error {
	if blocks.IsPreBellatrixVersion(blk.Block().Version()) { return nil }
	payload, err := blk.Block().Body().Execution()
	isEmpty, err := consensusblocks.IsEmptyExecutionData(payload)
	if isEmpty { return nil }
	if blocks.IsPreBellatrixVersion(stateVersion) { return s.validateMergeBlock(ctx, blk) }
	empty, err := consensusblocks.IsEmptyExecutionData(stateHeader)
	if !empty { return nil }  // Already post-merge, skip transition validation
	return s.validateMergeBlock(ctx, blk)
}

// beacon-chain/core/blocks/payload.go:156-173
func ValidatePayload(st state.BeaconState, payload interfaces.ExecutionData) error {
	random, err := helpers.RandaoMix(st, time.CurrentEpoch(st))
	if !bytes.Equal(payload.PrevRandao(), random) { return ErrInvalidPayloadPrevRandao }
	t, err := slots.StartTime(st.GenesisTime(), st.Slot())
	if payload.Timestamp() != uint64(t.Unix()) { return ErrInvalidPayloadTimeStamp }
	return nil
}
